CREATE ROLE authenticated; CREATE ROLE anon; CREATE ROLE service_role; CREATE SCHEMA auth; CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$SELECT nullif(current_setting('request.user_id',true),'')::uuid$$; CREATE TABLE company_members(company_id uuid,user_id uuid); CREATE FUNCTION is_company_member(u uuid,c uuid) RETURNS bool LANGUAGE sql STABLE AS $$ SELECT EXISTS(SELECT 1 FROM company_members WHERE user_id=u AND company_id=c) $$; CREATE FUNCTION can_delete_lenders(u uuid) RETURNS bool LANGUAGE sql AS $$SELECT u='11111111-1111-4111-8111-111111111111'::uuid$$;
CREATE TABLE funding_source_acquisition_plans("id" uuid NOT NULL DEFAULT gen_random_uuid(),"tenant_id" uuid NOT NULL,"year" int4 NOT NULL,"cadence" text NOT NULL,"period" int4 NOT NULL,"target_count" int4 NOT NULL DEFAULT 0,"updated_by" uuid,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_attachments("id" uuid NOT NULL DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL,"lender_name" text NOT NULL,"name" text NOT NULL,"file_path" text NOT NULL,"content_type" text,"size_bytes" int8 NOT NULL DEFAULT 0,"created_at" timestamptz NOT NULL DEFAULT now(),"category" text NOT NULL DEFAULT 'general'::text,"company_id" uuid);
CREATE TABLE lender_audit_logs("id" uuid NOT NULL DEFAULT gen_random_uuid(),"lender_id" uuid NOT NULL,"user_id" uuid,"user_display_name" text,"action" text NOT NULL,"field_changed" text,"old_value" text,"new_value" text,"metadata" jsonb,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_contacts("id" uuid NOT NULL DEFAULT gen_random_uuid(),"lender_id" uuid NOT NULL,"name" text NOT NULL,"title" text,"email" text,"phone" text,"is_primary" bool DEFAULT false,"notes" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),"geography" text,"contact_id" uuid,"city" text,"state" text,"country" text);
CREATE TABLE lender_disqualifications("id" uuid NOT NULL DEFAULT gen_random_uuid(),"deal_id" uuid NOT NULL,"deal_lender_id" uuid,"lender_name" text NOT NULL,"master_lender_id" uuid,"disqualified_by" uuid,"reason_category" text NOT NULL,"reason_details" text,"deal_size" numeric,"deal_industry" text,"deal_geography" text,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_doc_flags("id" uuid NOT NULL DEFAULT gen_random_uuid(),"company_id" uuid NOT NULL,"lender_name" text NOT NULL,"has_nda" bool NOT NULL DEFAULT false,"has_marketing" bool NOT NULL DEFAULT false,"updated_by" uuid,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_duplicate_dismissals("id" uuid NOT NULL DEFAULT gen_random_uuid(),"company_id" uuid NOT NULL,"dismissal_key" text NOT NULL,"lender_ids" uuid[] NOT NULL,"created_by" uuid NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_fit_attributes("id" uuid NOT NULL DEFAULT gen_random_uuid(),"master_lender_id" uuid,"lender_name" text NOT NULL,"company_id" uuid,"summary" text,"positive_signals" jsonb NOT NULL DEFAULT '[]'::jsonb,"negative_signals" jsonb NOT NULL DEFAULT '[]'::jsonb,"exclusions" jsonb NOT NULL DEFAULT '[]'::jsonb,"nuanced_preferences" jsonb NOT NULL DEFAULT '[]'::jsonb,"embedding" text,"source_hash" text,"model_version" text,"extracted_at" timestamptz NOT NULL DEFAULT now(),"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_history_warning_dismissals("id" uuid NOT NULL DEFAULT gen_random_uuid(),"deal_id" uuid NOT NULL,"lender_name" text NOT NULL,"dismissed_by" uuid NOT NULL,"dismissed_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_match_rules("id" uuid NOT NULL DEFAULT gen_random_uuid(),"rule_type" text NOT NULL,"lender_id" uuid,"lender_name" text,"applies_when" jsonb,"reason" text NOT NULL,"delta" int4,"active" bool NOT NULL DEFAULT true,"created_by" uuid NOT NULL,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_notes("id" uuid NOT NULL DEFAULT gen_random_uuid(),"lender_name" text NOT NULL,"master_lender_id" uuid,"author_user_id" uuid NOT NULL,"body" text NOT NULL,"is_flag" bool NOT NULL DEFAULT false,"tags" text[] DEFAULT '{}'::text[],"company_id" uuid,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_pass_detections("id" uuid NOT NULL DEFAULT gen_random_uuid(),"deal_id" uuid NOT NULL,"deal_lender_id" uuid,"lender_name" text NOT NULL,"gmail_message_id" text NOT NULL,"thread_id" text,"sender_email" text,"sender_name" text,"confidence" text NOT NULL,"is_pass" bool NOT NULL DEFAULT false,"reason_summary" text,"source_quote" text,"status" text NOT NULL DEFAULT 'pending'::text,"confirmed_at" timestamptz,"confirmed_by" uuid,"dismissed_at" timestamptz,"dismissed_by" uuid,"edited_reason" text,"raw_classification" jsonb,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_pass_patterns("id" uuid NOT NULL DEFAULT gen_random_uuid(),"master_lender_id" uuid,"lender_name" text NOT NULL,"reason_category" text NOT NULL,"pattern_type" text NOT NULL,"pattern_value" text NOT NULL,"confidence_score" numeric DEFAULT 0.5,"occurrence_count" int4 DEFAULT 1,"last_updated" timestamptz NOT NULL DEFAULT now(),"created_at" timestamptz NOT NULL DEFAULT now());
CREATE TABLE lender_sync_request_decisions("id" uuid NOT NULL DEFAULT gen_random_uuid(),"request_id" uuid NOT NULL,"field_name" text NOT NULL,"scope" text NOT NULL,"existing_value" jsonb,"incoming_value" jsonb,"action" text NOT NULL,"decided_by" uuid,"decided_at" timestamptz NOT NULL DEFAULT now(),"notes" text);
CREATE TABLE lender_sync_requests("id" uuid NOT NULL DEFAULT gen_random_uuid(),"source_system" text NOT NULL DEFAULT 'flex'::text,"source_lender_id" text,"request_type" text NOT NULL,"incoming_data" jsonb NOT NULL,"existing_lender_id" uuid,"existing_lender_name" text,"changes_diff" jsonb,"status" text NOT NULL DEFAULT 'pending'::text,"processed_by" uuid,"processed_at" timestamptz,"processing_notes" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),"confidence" text,"suggested_action" text,"match_candidates" jsonb NOT NULL DEFAULT '[]'::jsonb,"match_reason" text,"conflict_count" int4 NOT NULL DEFAULT 0,"contact_change_count" int4 NOT NULL DEFAULT 0,"assigned_reviewer_id" uuid);
CREATE TABLE master_lenders("id" uuid NOT NULL DEFAULT gen_random_uuid(),"user_id" uuid NOT NULL,"company_id" uuid,"email" text,"name" text NOT NULL,"lender_type" text,"loan_types" text[],"sub_debt" text,"cash_burn" text,"sponsorship" text,"min_revenue" numeric,"ebitda_min" numeric,"min_deal" numeric,"max_deal" numeric,"industries" text[],"industries_to_avoid" text[],"b2b_b2c" text,"refinancing" text,"company_requirements" text,"deal_structure_notes" text,"geo" text,"contact_name" text,"contact_title" text,"relationship_owners" text,"lender_one_pager_url" text,"referral_lender" text,"referral_fee_offered" text,"referral_agreement" text,"nda" text,"onboarded_to_flex" text,"upfront_checklist" text,"post_term_sheet_checklist" text,"gift_address" text,"external_created_by" text,"external_last_modified" timestamptz,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),"tier" text,"active" bool DEFAULT true,"sync_source" text DEFAULT 'naitive'::text,"flex_lender_id" text,"last_synced_from_flex" timestamptz,"contact_phone" text,"tags" text[] NOT NULL DEFAULT '{}'::text[],"website" text,"linkedin_url" text,"address" text,"phone" text,"funding_source_notes" text,"about_notes" text,"crm_company_id" uuid,"sweet_spot_min" numeric,"sweet_spot_max" numeric,"min_gross_margin_pct" numeric,"max_leverage" numeric,"geographies" text[],"geographies_excluded" text[],"sponsor_requirement" text,"appetite_status" text DEFAULT 'active'::text,"criteria_confidence" text,"criteria_reviewed_at" timestamptz,"contact_geography" text,"city" text,"state" text,"country" text,"resp_emails_sent" int4,"resp_replies_received" int4,"resp_reply_rate" numeric,"resp_median_hours_to_reply" numeric,"resp_reply_rate_excl_mass" numeric,"resp_last_reply_date" date,"resp_rating" text,"resp_emails_sent_l12m" int4,"resp_reply_rate_l12m" numeric,"resp_window_label" text,"resp_updated_at" timestamptz);
CREATE TABLE deals(id uuid,company_id uuid,current_lender_id uuid); CREATE TABLE deal_lenders(id uuid,deal_id uuid,master_lender_id uuid,name text); CREATE TABLE contacts(id uuid,company_id uuid); CREATE TABLE crm_companies(id uuid,org_company_id uuid); CREATE FUNCTION fn_lender_contact_resolve_crm(uuid,text,text,text,text,text,text,text) RETURNS uuid LANGUAGE sql AS $$SELECT NULL::uuid$$; GRANT USAGE ON SCHEMA public,auth TO authenticated; GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA public TO authenticated;
ALTER TABLE master_lenders ADD PRIMARY KEY(id);
ALTER TABLE lender_notes ADD FOREIGN KEY(master_lender_id) REFERENCES master_lenders(id) ON DELETE SET NULL;
ALTER TABLE lender_contacts ADD FOREIGN KEY(lender_id) REFERENCES master_lenders(id) ON DELETE CASCADE;
ALTER TABLE lender_audit_logs ADD FOREIGN KEY(lender_id) REFERENCES master_lenders(id) ON DELETE CASCADE;
ALTER TABLE deal_lenders ADD FOREIGN KEY(master_lender_id) REFERENCES master_lenders(id) ON DELETE CASCADE;
